 1	//Algorithm 1: From left to right return the first
 2	method mmaximum1(v:array<int>) returns (i:int) 
 3	requires v.Length>0
 4	ensures 0<=i<v.Length 
 5	ensures forall k:: 0<=k<v.Length ==> v[i]>=v[k]
 6	{
 7	    var j:=1; i:=0;
 8	    while(j<v.Length)
 9	        decreases v.Length - j
10	        invariant 0<=j<=v.Length
11	        invariant 0<=i<j
12	        invariant forall k:: 0<=k<j ==> v[i] >= v[k]
13	    {
14	        if(v[j] > v[i]){i:=j;}
15	        j:=j+1;
16	    }
17	}
18	
19	//Algorithm 2: From right to left return the last
20	method mmaximum2(v:array<int>) returns (i:int) 
21	requires v.Length>0
22	ensures 0<=i<v.Length 
23	ensures forall k:: 0<=k<v.Length ==> v[i]>=v[k]
24	{
25	    var j:=v.Length-2; i:=v.Length - 1;
26	    while(j>=0)
27	        decreases j
28	        invariant 0<=i<v.Length
29	        invariant -1<=j<v.Length-1
30	        invariant forall k :: v.Length>k>j ==> v[k]<=v[i]
31	    {
32	        if(v[j] > v[i]){i:=j;}
33	        j:=j-1;
34	    }
35	}
